// Google search API
const googleSearchAPI = 'https://www.google.com/search?q=';
const apiKey = 'YOUR_GOOGLE_API_KEY';

// Search component JavaScript
const searchComponent = document.querySelector('.search-component');
const searchInput = document.querySelector('.search-input');
const searchButton = document.querySelector('.search-button');
const searchSuggestions = document.querySelector('.search-suggestions');
const searchError = document.querySelector('.search-error');

let searchQuery = '';
let searchResults = [];
let searchTimeout = null;

// Handle search input
searchInput.addEventListener('input', (e) => {
  clearTimeout(searchTimeout);
  searchTimeout = setTimeout(() => {
    searchQuery = e.target.value.trim();
    if (searchQuery.length > 2) {
      // Make API request to Google search
      fetch(`${googleSearchAPI}${searchQuery}`)
        .then((response) => response.json())
        .then((data) => {
          searchResults = data.results;
          updateSearchSuggestions();
        })
        .catch((error) => {
          console.error(error);
          updateSearchError();
        });
    }
  }, 500);
});

// Handle search button click
searchButton.addEventListener('click', () => {
  if (searchQuery.length > 2) {
    // Make API request to Google search with search query
    fetch(`${googleSearchAPI}${searchQuery}&key=${apiKey}`)
      .then((response) => response.json())
      .then((data) => {
        searchResults = data.results;
        updateSearchSuggestions();
      })
      .catch((error) => {
        console.error(error);
        updateSearchError();
      });
  }
});

// Update search suggestions
