```c
#include <Windows.h>
#include <iostream>
#include <cmath>
#include <cstdlib>
#include <ctime>

const int N = 4; // количество потоков
const int M = 100; // количество интервалов для интегралa

// функция для вычисления интеграла методом прямоугольников
double integrate_rectangles(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += f(a + i * h);
    }
    return result * h;
}

// функция для вычисления интеграла методом трапеций
double integrate_trapezes(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        double x1 = a + i * h;
        double x2 = a + (i + 1) * h;
        result += (f(x1) + f(x2)) * h / 2;
    }
    return result;
}

// функция для вычисления интеграла методом Симпсона
double integrate_simpson(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        double x1 = a + i * h;
        double x2 = a + (i + 1) * h;
        double x3 = a + (i + 2) * h;
        result += (f(x1) + f(x3) + 4 * f(x2)) * h / 3;
    }
    return result;
}

// функция для вычисления интеграла
class Integrator {
public:
    double integrate(double (*f)(double), double a, double b, int n) {
        double result = 0;
        for (int i = 0; i < N; i++) {
            result += integrate_rectangles(f, a, b, n);
        }
        return result / N;
    }
};

// поток для вычисления интеграла
DWORD WINAPI thread_func(LPVOID param) {
    Integrator integrator;
    double (*f)(double) = (double (*) (double))param;
    double a = 0;
    double b = 1;
    int n = M;
    double result = integrator.integrate(f, a, b, n);
    {
        HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
        WaitSingleObject(hMutex, INFINITE);
        printf("Токен %d: интеграл = %f\n", GetCurrentThreadId(), result);
        ReleaseMutex(hMutex);
    }
    return 0;
}

int main() {
    // создаем мьютекс для синхронизации вывода
    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
    HANDLE hSemaphore = CreateSemaphore(NULL, 0, N - 1, NULL);

    // создаем потоки для вычисления интеграла
    HANDLE threads[N];
    for (int i = 0; i < N; i++) {
        double (*f)(double) = NULL; // функция для вычисления интеграла
        if (i == 0) {
            f = [](double x) { return x * x; };
        } else if (i == 1) {
            f = [](double x) { return cos(x); };
        } else if (i == 2) {
            f = [](double x) { return exp(x); };
        }
        threads[i] = CreateThread(NULL, 0, &thread_func, f, 0, NULL);
    }

    // ожидаем завершения вычислений все потоки
    for (int i = 0; i < N; i++) {
        ReleaseSemaphore(hSemaphore, 1);
        WaitForSingleObject(threads[i], INFINITE);
    }

    // вывод результатов
    {
        HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
        WaitSingleObject(hMutex, INFINITE);
        printf("Результаты вычислений:\n");
        for (int i = 0; i < N; i++) {
            printf("Токен %d: интеграл = ?\n", GetCurrentThreadId());
        }
        ReleaseMutex(hMutex);
    }

    // уничтожаем потоки
    for (int i = 0; i < N; i++) {
        CloseHandle(threads[i]);
    }
    CloseHandle(hMutex);
    CloseHandle(hSemaphore);

    return 0;
}
```
