#include <iostream>
using namespace std;

// Estructura del nodo del árbol binario
struct Nodo {
    int valor;
    Nodo* izquierda;
    Nodo* derecha;
};

// Función para crear un nuevo nodo
Nodo* creaNodo(int valor) {
    Nodo* nodo = new Nodo();
    nodo->valor = valor;
    nodo->izquierda = nullptr;
    nodo->derecha = nullptr;
    return nodo;
}

// Función para insertar un valor en el árbol binario
Nodo* inserts(Nodo* raiz, int valor) {
    if (raiz == nullptr) {
        raiz = creaNodo(valor);
    } else if (valor < raiz->valor) {
        raiz->izquierda = inserts(raiz->izquierda, valor);
    } else if (valor > raiz->valor) {
        raiz->derecha = inserts(raiz->derecha, valor);
    }
    return raiz;
}

// Función para buscar un valor en el árbol binario
bool busqueda(Nodo* raiz, int valor) {
    if (raiz == nullptr) {
        return false;
    } else if (valor == raiz->valor) {
        return true;
    } else if (valor < raiz->valor) {
        return busqueda(raiz->izquierda, valor);
    } else {
        return busqueda(raiz->derecha, valor);
    }
}

// Función para imprimir el árbol binario
void imprimeArbol(Nodo* raiz, string indent = "") {
    if (raiz != nullptr) {
        imprimeArbol(raiz->derecha, indent + "    ");
        cout << indent << raiz->valor << endl;
        imprimeArbol(raiz->izquierda, indent + "    ");
    }
}

int main() {
    Nodo* raiz = nullptr;

    // Insertar valores en el árbol binario
