    inserts(raiz, 2);
    inserts(raiz, 8);
    inserts(raiz, 3);
    inserts(raiz, 7);
    inserts(raiz, 9);

    // Imprimir el árbol binario
    cout << "Árbol binario:" << endl;
    imprimeArbol(raiz);

    // Buscar un valor en el árbol binario
    int valor = 7;
